/**
 * Personal API token rows. Only the hash of a secret is ever stored, and no
 * function here returns it: reads hand back `ApiToken`, and the one lookup by
 * hash resolves the same shape.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface NewApiToken {
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  prefix: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
}

/**
 * Counts the user's usable tokens and inserts in one synchronous transaction,
 * so two concurrent creations cannot both slip under the limit. Resolves
 * `null` (and stores nothing) when the limit is already reached.
 */
export async function insertApiTokenWithinLimit(
  input: NewApiToken,
  limit: number,
  now: IsoTimestamp,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const used = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, input.orgId),
          eq(apiTokens.userId, input.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, now),
        ),
      )
      .get();

    if ((used?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: input.orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        prefix: input.prefix,
        tokenHash: input.tokenHash,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: input.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Newest first; `rowid` breaks ties between tokens created in the same millisecond. */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), sql`${apiTokens}.rowid desc`)
    .all()
    .map(toApiToken);
}

/** Every token of the user in the org that has not been revoked yet, expired ones included. */
export async function listUnrevokedApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .all()
    .map(toApiToken);
}

