async function revokeAndAudit(
  token: ApiToken,
  actorId: UserId | null,
): Promise<ApiToken> {
  const revoked = await apiTokenRepo.markApiTokenRevoked(
    token.orgId,
    token.id,
    toIsoTimestamp(new Date()),
  );

  if (revoked === null) {
    return (
      (await apiTokenRepo.findApiTokenById(token.orgId, token.id)) ?? token
    );
  }

  await emit("api_token.revoked", {
    ...envelope(revoked.orgId, actorId),
    tokenId: revoked.id,
    userId: revoked.userId,
    name: revoked.name,
    scope: revoked.scope,
  });

  return revoked;
}

/**
 * Attaches the handler that revokes a removed member's tokens. Called once from
 * `event-registry`.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listUnrevokedApiTokensForUser(
      payload.orgId,
      payload.userId,
    );
    for (const token of tokens) {
      await revokeAndAudit(token, payload.actorId);
    }
  });
}
