import { beforeAll, expect, it } from "vitest";
import { useTemporaryDatabase, createTenant } from "./_support/fixtures";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as svc from "@/server/services/api-token-service";
import * as memberSvc from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as activityRepo from "@/server/repositories/activity-repository";

beforeAll(async () => { await useTemporaryDatabase(); registerEventHandlers(); });

it("works", async () => {
  const t = await createTenant("acme");
  const a = t.actors.member;
  const { token, apiToken } = await svc.createApiToken(a, { orgId: a.orgId, name: " ci ", scope: "write", expiresInDays: 30 });
  expect(token.startsWith("tfk_")).toBe(true);
  expect(apiToken.prefix).toBe(token.slice(0, 12));
  expect(await svc.authenticateApiToken(token)).toEqual({ userId: a.userId, orgId: a.orgId, role: "member" });
  await expect(svc.createApiToken(t.actors.viewer, { orgId: a.orgId, name: "x", scope: "write", expiresInDays: 1 })).rejects.toThrow();
  for (let i = 0; i < 4; i++) await svc.createApiToken(a, { orgId: a.orgId, name: "n" + i, scope: "read", expiresInDays: 1 });
  await expect(svc.createApiToken(a, { orgId: a.orgId, name: "n", scope: "read", expiresInDays: 1 })).rejects.toThrow();
  const list = await svc.listApiTokens(a, a.orgId);
  expect(list.length).toBe(5);
  expect(list[0]!.name).toBe("n3");
  const r1 = await svc.revokeApiToken(a, a.orgId, apiToken.id);
  const r2 = await svc.revokeApiToken(a, a.orgId, apiToken.id);
  expect(r2.revokedAt).toBe(r1.revokedAt);
  expect(await svc.authenticateApiToken(token)).toBeNull();
  const member = await memberRepo.findMember(a.orgId, a.userId);
  await memberSvc.removeMember(t.actors.admin, { orgId: a.orgId, memberId: member!.id } as never);
  const page = await activityRepo.listActivity({ orgId: a.orgId, limit: 50, cursor: null } as never);
  console.log(page.items.map((e) => e.action + ":" + e.actorId));
  const after = await svc.listApiTokens(t.actors.admin, a.orgId, a.userId);
  expect(after.every((x) => x.revokedAt !== null)).toBe(true);
});
